update asset
set parse_status = #{parseStatus},
    index_status = #{indexStatus},
    segment_count = #{segmentCount},
    indexed_segment_count = #{indexedSegmentCount},
    active_index_generation = #{targetGeneration},
    error_code = null,
    error_message = null,
    updated_by = #{updatedBy},
    updated_at = #{updatedAt}
where id = #{assetId}
  and kb_id = #{kbId}
  and deleted_at is null
  and active_index_generation = #{expectedActiveGeneration}
  and active_index_generation < #{targetGeneration}

update asset
